(3103, 1401, '_form', '<div class=\"row form--square text-center\">\n <div class=\"input-with-icon\">\n    <i class=\"icon-MaleFemale\"></i>[text* your-name placeholder \"Name/Names\"]\n  </div>\n[radio radio-881 default:1 \"Can\'t Wait\" \"Can\'t Come\"]\n  <div class=\"input-with-icon\">\n    <i class=\"icon-Music-Note2\"></i>[text* your-email placeholder \"Song Request?\"]\n  </div>\n[submit \"RSVP\"]\n</div>'),
