(829, 6, '2016-06-10 12:08:29', '2016-06-10 12:08:29', '[vc_row full_width=\"stretch_row\" content_placement=\"middle\" parallax=\"content-moving\" parallax_image=\"63\" el_class=\"height-70\" css=\".vc_custom_1470738579075{padding-top: 300px !important;}\"][vc_column][vc_column_text]\n<h1 style=\"text-align: center\">Digital Delivered.</h1>\n[/vc_column_text][/vc_column][/vc_row][vc_row el_class=\"section--overlap\"][vc_column][pillar_portfolio pppage=\"6\" layout=\"grid-2col\"][/vc_column][/vc_row][vc_row][vc_column width=\"1/6\"][/vc_column][vc_column width=\"2/3\"][vc_column_text]\n<h3 style=\"text-align: center\">Start building with Pillar</h3>\n<p class=\"lead\" style=\"text-align: center\">We\'d love to hear from you to discuss web design, product development or to hear your new startup idea.</p>\n<p style=\"text-align: center\"><a class=\"btn btn--primary\" href=\"/pages/contact-simple/\"><span class=\"btn__text\">LET\'S TALK TURKEY</span></a></p>\n[/vc_column_text][/vc_column][vc_column width=\"1/6\"][/vc_column][/vc_row]', 'Column', '', 'publish', 'closed', 'closed', '', 'column', '', '', '2016-06-10 12:08:29', '2016-06-10 12:08:29', '', 362, 'http://tommustester.wpengine.com/?page_id=829', 0, 'page', '', 0),
(838, 6, '2016-06-10 12:17:36', '2016-06-10 12:17:36', '[vc_row full_width=\"stretch_row\"][vc_column][pillar_hero layout=\"bottom-left\" image=\"219\"][vc_column_text]<img class=\"size-medium wp-image-575 alignnone\" src=\"http://www.ondoweb.ondostate.gov.ng/bir/files/2016/06/logo-large-light-300x117.png\" alt=\"logo-large-light\" width=\"300\" height=\"117\" />\n<p class=\"lead\">A beautiful collection of\nhand-crafted web components</p>\n[/vc_column_text][pillar_video_modal layout=\"embed-large\" colour=\"video-play-icon--light\" text=\"Watch The Trailer\" embed=\"https://www.youtube.com/watch?v=aiTIrxGT4Dk\"][/pillar_hero][/vc_column][/vc_row][vc_row full_width=\"stretch_row\"][vc_column][pillar_portfolio pppage=\"6\" layout=\"grid-2col\"][/vc_column][/vc_row]', 'Fullwidth', '', 'publish', 'closed', 'closed', '', 'fullwidth', '', '', '2016-06-10 12:17:36', '2016-06-10 12:17:36', '', 362, 'http://tommustester.wpengine.com/?page_id=838', 0, 'page', '', 0),
(846, 6, '2016-06-10 12:24:03', '2016-06-10 12:24:03', '[vc_row full_width=\"stretch_row\" parallax=\"content-moving\" parallax_image=\"848\" css=\".vc_custom_1470738788249{padding-top: 400px !important;}\" el_class=\"height-90\"][vc_column width=\"1/6\"][/vc_column][vc_column width=\"2/3\"][vc_column_text]\n<p class=\"lead\" style=\"text-align: center\">Hi, I’m David, I’m a serial entrepreneur turned interactive strategist specializing in digital product development, creative direction, and marketing. My most recent project is Mylo, a men’s style advice app and staples shop.</p>\n[/vc_column_text][/vc_column][vc_column width=\"1/6\"][/vc_column][/vc_row][vc_row el_class=\"section--overlap\"][vc_column][pillar_portfolio pppage=\"6\" layout=\"grid-2col\"][/vc_column][/vc_row][vc_row el_class=\"bg--dark\" css=\".vc_custom_1465561534826{margin-top: -200px !important;padding-top: 220px !important;}\"][vc_column width=\"1/6\"][/vc_column][vc_column width=\"2/3\"][vc_column_text]\n<p class=\"lead\" style=\"text-align: center\">Interested in working with me on an upcoming project?</p>\n<p style=\"text-align: center\"><a class=\"btn btn--primary\" href=\"/pages/contact-simple/\"><span class=\"btn__text\">LET\'S TALK TURKEY</span></a></p>\n[/vc_column_text][/vc_column][vc_column width=\"1/6\"][/vc_column][/vc_row]', 'Personal', '', 'publish', 'closed', 'closed', '', 'personal', '', '', '2016-06-10 12:24:03', '2016-06-10 12:24:03', '', 362, 'http://tommustester.wpengine.com/?page_id=846', 0, 'page', '', 0);
