(2247, 6, '2017-10-25 12:27:55', '2017-10-25 12:27:55', '[vc_row parallax=\"content-moving\" parallax_image=\"272\" css=\".vc_custom_1464949547391{padding-top: 250px !important;padding-bottom: 220px !important;}\"][vc_column][vc_column_text css_animation=\"bottom-to-top\"]\r\n<h3 style=\"text-align: center\">Your Creative Collective</h3>\r\n<p class=\"lead\" style=\"text-align: center\">Our rigorous process ensures your project is managed strategically and efficiently from\r\ninitial conception through to final delivery and after-sales support.</p>\r\n[/vc_column_text][/vc_column][/vc_row][vc_row][vc_column][pillar_team pppage=\"6\"][/vc_column][/vc_row][vc_row parallax=\"content-moving\" parallax_image=\"202\"][vc_column][vc_column_text css=\".vc_custom_1473784204587{margin-bottom: 0px !important;}\"]\r\n<h4 style=\"text-align: center\">What can Pillar do for your business?</h4>\r\n<p style=\"text-align: center\"><a class=\"btn btn--primary\" href=\"/pages/contact-simple/\"><span class=\"btn__text\">ARRANGE A CONSULTATION</span></a></p>\r\n[/vc_column_text][/vc_column][/vc_row]', 'About Management Team', '', 'inherit', 'closed', 'closed', '', '271-revision-v1', '', '', '2017-10-25 12:27:55', '2017-10-25 12:27:55', '', 271, 'http://www.ondoweb.ondostate.gov.ng/bir/2017/10/25/271-revision-v1/', 0, 'revision', '', 0),
(2270, 6, '2017-10-25 13:52:13', '2017-10-25 13:52:13', '[vc_row full_width=\"stretch_row\"][vc_column][vc_gmaps link=\"#E-8_\"][/vc_column][/vc_row][vc_row el_class=\"section--overlap\"][vc_column width=\"1/3\"][pillar_icon_box icon=\"icon-Map-Marker2\" layout=\"boxed-large\" title=\"Drop on in\"]\r\n<p style=\"text-align: center\">SAkure express/Akure\r\nAlagbaka quarters, Akure\r\nOndo State[/pillar_icon_box][/vc_column][vc_column width=\"1/3\"][pillar_icon_box icon=\"icon-Phone-2\" layout=\"boxed-large\" title=\"Give us a call\"]</p>\r\n<p style=\"text-align: center\">Office: (03) 9283 2617\r\nFax: +61 3827 3590</p>\r\n[/pillar_icon_box][/vc_column][vc_column width=\"1/3\"][pillar_icon_box icon=\"icon-Computer\" layout=\"boxed-large\" title=\"Connect Online\"]\r\n<p style=\"text-align: center\">Email: <a href=\"#\">hello@pillarstudio.net</a>\r\nTwitter: <a href=\"#\">@pillarstudio</a></p>\r\n[/pillar_icon_box][/vc_column][/vc_row][vc_row][vc_column width=\"1/6\"][/vc_column][vc_column width=\"2/3\"][vc_column_text]\r\n<h4 class=\"text-center\" style=\"text-align: center\">Or reach us right here…</h4>\r\n[/vc_column_text][contact-form-7 id=\"1003\"][/vc_column][vc_column width=\"1/6\"][/vc_column][/vc_row]', 'Contact Us', '', 'inherit', 'closed', 'closed', '', '157-revision-v1', '', '', '2017-10-25 13:52:13', '2017-10-25 13:52:13', '', 157, 'http://www.ondoweb.ondostate.gov.ng/bir/2017/10/25/157-revision-v1/', 0, 'revision', '', 0),
